components.css:
.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 12px; border: 1px solid transparent; border-radius: 6px; white-space: nowrap; user-select: none; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; line-height: 20px; font-weight: 500; transition: background-color 150ms cubic-bezier(0.16,1,0.3,1), border-color 150ms cubic-bezier(0.16,1,0.3,1), color 150ms cubic-bezier(0.16,1,0.3,1), box-shadow 150ms cubic-bezier(0.16,1,0.3,1); }
.ds-btn-sm { height: 28px; padding: 0 8px; font-size: 12px; line-height: 18px; }
.ds-btn-primary { background: #1f6feb; border-color: #1f6feb; color: #ffffff; box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.5); }
.ds-btn-primary:hover { filter: brightness(1.1); }

.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 12px; border: 1px solid transparent; border-radius: 6px; white-space: nowrap; user-select: none; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; line-height: 20px; font-weight: 500; transition: background-color 150ms cubic-bezier(0.16,1,0.3,1), border-color 150ms cubic-bezier(0.16,1,0.3,1), color 150ms cubic-bezier(0.16,1,0.3,1), box-shadow 150ms cubic-bezier(0.16,1,0.3,1); }
.ds-btn-sm { height: 28px; padding: 0 8px; font-size: 12px; line-height: 18px; }
.ds-btn-default { background: #1b1f27; border-color: #333a45; color: #e8ebf0; box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.5); }
.ds-btn-default:hover { background: #212632; border-color: #6e7887; }

.ds-btn { display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 32px; padding: 0 12px; border: 1px solid transparent; border-radius: 6px; white-space: nowrap; user-select: none; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; line-height: 20px; font-weight: 500; transition: background-color 150ms cubic-bezier(0.16,1,0.3,1), border-color 150ms cubic-bezier(0.16,1,0.3,1), color 150ms cubic-bezier(0.16,1,0.3,1), box-shadow 150ms cubic-bezier(0.16,1,0.3,1); }
.ds-btn-sm { height: 28px; padding: 0 8px; font-size: 12px; line-height: 18px; }
.ds-btn-danger { background: transparent; border-color: rgb(248 81 73 / 0.5); color: #f85149; }
.ds-btn-danger:hover { background: #2d1416; border-color: #f85149; }

.ds-iconbtn { display: grid; place-items: center; width: 32px; height: 32px; border: 0; border-radius: 6px; background: transparent; color: #9aa3b2; }
.ds-iconbtn:hover { background: #212632; color: #e8ebf0; }
.ds-iconbtn-sm { width: 28px; height: 28px; }

.ds-field { display: flex; flex-direction: column; gap: 6px; }
.ds-label { font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 12px; line-height: 18px; font-weight: 500; color: #9aa3b2; }
.ds-input { width: 100%; height: 32px; padding: 0 10px; border: 1px solid #333a45; border-radius: 6px; background: #1b1f27; color: #e8ebf0; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; }
.ds-input::placeholder { color: #6e7887; opacity: 1; }
.ds-input:focus { outline: none; border-color: #1f6feb; box-shadow: 0 0 0 2px rgb(31 111 235 / 0.3); }

.ds-badge { display: inline-flex; align-items: center; gap: 4px; height: 20px; padding: 0 8px; border: 1px solid transparent; border-radius: 999px; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 11px; line-height: 16px; font-weight: 500; }
.ds-badge-accent { background: #16304f; border-color: rgb(31 111 235 / 0.4); color: #6ea8ff; }
.ds-badge-warn { background: rgb(210 153 34 / 0.12); border-color: rgb(210 153 34 / 0.4); color: #d29922; }
.ds-badge-danger { background: #2d1416; border-color: rgb(248 81 73 / 0.4); color: #f85149; }

.ds-annot { display: inline-flex; align-items: baseline; gap: 5px; white-space: nowrap; }
.ds-annot-k { font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 11px; font-weight: 500; color: #6e7887; }
.ds-annot-v { font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 13px; color: #e8ebf0; font-variant-numeric: tabular-nums; }

.ds-appbar { display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 8px; background: #15181e; border-bottom: 1px solid #242932; }
.ds-mark { width: 24px; height: 24px; border-radius: 6px; background: #1f6feb; }
.ds-wordmark { font-family: 'Segoe UI Variable Display', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; font-weight: 600; color: #e8ebf0; }
.ds-cmd { display: flex; align-items: center; height: 32px; flex: 1; max-width: 42rem; padding: 0 10px; border: 1px solid #333a45; border-radius: 6px; background: #1b1f27; color: #6e7887; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; }

.ds-strip { display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 8px 0 4px; background: #15181e; border-bottom: 1px solid #242932; }
.ds-tab { display: flex; align-items: center; gap: 8px; height: 32px; padding: 0 10px; border: 1px solid transparent; border-radius: 6px; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 12px; color: #9aa3b2; }
.ds-tab-active { background: #1b1f27; border-color: #242932; color: #e8ebf0; box-shadow: 0 1px 2px 0 rgb(0 0 0 / 0.5); }
.ds-tab:not(.ds-tab-active):hover { background: #212632; color: #e8ebf0; }
.ds-dot { width: 10px; height: 10px; border-radius: 999px; border: 1px solid #333a45; }
.ds-actions { margin-left: auto; display: flex; align-items: center; gap: 6px; }

.ds-dialog { display: flex; flex-direction: column; border: 1px solid #333a45; border-radius: 8px; background: #1b1f27; overflow: hidden; box-shadow: 0 12px 32px -8px rgb(0 0 0 / 0.65), 0 4px 8px -4px rgb(0 0 0 / 0.5); }
.ds-dialog-head { padding: 14px 16px 12px; }
.ds-dialog-title { margin: 0; font-family: 'Segoe UI Variable Display', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 20px; line-height: 28px; font-weight: 600; color: #e8ebf0; }
.ds-dialog-body { padding: 0 16px 16px; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 14px; color: #e8ebf0; }
.ds-dialog-foot { display: flex; justify-content: flex-end; gap: 8px; padding: 12px 16px; background: #15181e; border-top: 1px solid #242932; }

.ds-menu { min-width: 13rem; padding: 4px; border: 1px solid #333a45; border-radius: 8px; background: #1b1f27; box-shadow: 0 12px 32px -8px rgb(0 0 0 / 0.65), 0 4px 8px -4px rgb(0 0 0 / 0.5); }
.ds-menu-item { display: flex; align-items: center; gap: 10px; padding: 6px 10px; border-radius: 4px; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 12px; line-height: 18px; color: #e8ebf0; }
.ds-menu-item-on { background: #212632; }

.ds-grid { font-family: 'JetBrains Mono', 'Cascadia Mono', 'SF Mono', Menlo, Consolas, monospace; font-size: 13px; line-height: 20px; font-variant-numeric: tabular-nums; }
.ds-grid-head { display: flex; height: 44px; background: #15181e; }
.ds-th { display: flex; flex-direction: column; justify-content: center; padding: 0 6px; border-right: 1px solid #242932; border-bottom: 1px solid #242932; }
.ds-th-name { font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 12px; font-weight: 600; color: #e8ebf0; }
.ds-th-type { font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 11px; color: #9aa3b2; }
.ds-tr { display: flex; height: 30px; }
.ds-tr-sel { background: rgb(22 48 79 / 0.4); }
.ds-gutter { width: 60px; display: flex; align-items: center; justify-content: flex-end; padding-right: 8px; border-right: 1px solid #242932; background: #15181e; color: #6e7887; font-size: 11px; }
.ds-gutter-sel { background: #1f6feb; color: #ffffff; font-weight: 500; }
.ds-td { display: flex; align-items: center; padding: 0 6px; border-right: 1px solid #242932; border-bottom: 1px solid #242932; }
.ds-num { justify-content: flex-end; }
.ds-td-sel { background: #16304f; }

.ds-treerow { display: flex; align-items: center; gap: 6px; padding: 6px 8px 6px 20px; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 13px; line-height: 20px; color: #e8ebf0; }
.ds-treerow:hover { background: #212632; }
.ds-chev { display: grid; place-items: center; width: 16px; color: #9aa3b2; }
.ds-est { margin-left: auto; padding-left: 8px; font-size: 11px; color: #6e7887; font-variant-numeric: tabular-nums; }

.ds-cell { display: inline-block; width: 16px; height: 16px; border: 1px solid #333a45; border-radius: 3px; background: transparent; }
.ds-cell:hover { border-color: #1f6feb; }
.ds-cell-on { background: #1f6feb; border-color: #1f6feb; }
.ds-cell-off { opacity: 0.45; cursor: not-allowed; }

.ds-empty { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 12px; padding: 32px; text-align: center; font-family: 'Segoe UI Variable Text', 'Segoe UI', -apple-system, BlinkMacSystemFont, ui-sans-serif, Roboto, 'Helvetica Neue', Arial, sans-serif; }
.ds-empty-icon { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 999px; background: #15181e; color: #9aa3b2; }
.ds-empty-title { font-size: 16px; line-height: 24px; font-weight: 600; color: #e8ebf0; }
.ds-empty-body { max-width: 28rem; margin: 0; font-size: 12px; line-height: 18px; color: #9aa3b2; }
